import styled from '@emotion/styled';

const BAR_CHART_MAX_WIDTH = 312;
const DEFAULT_CHART_WRAPPER_HEIGHT = '316px';
const PHI_LINE_TO_BAR_CHART_OVERLAP = 12;

export const PHI_LINE_COMPARISON_ROW_HEIGHT = 40;
export const PHI_COMPARISON_TABLE_ROW_HEIGHT = 40;

export const phiLineComparisonRowConfig = {
  heights: [PHI_LINE_COMPARISON_ROW_HEIGHT, PHI_COMPARISON_TABLE_ROW_HEIGHT],
  alignItems: 'center' as const,
  boxSizing: 'border-box' as const,
  padding: '0 8px',
};

export const StyledChartsGrid = styled.div({
  display: 'grid',
  gridTemplateColumns: `minmax(0, 1fr) ${BAR_CHART_MAX_WIDTH}px`,
  columnGap: 0,
  alignItems: 'start',
  paddingBottom: 0,
  width: '100%',
  minWidth: 0,
  boxSizing: 'border-box',

  '@media (max-width: 1096px)': {
    display: 'flex',
    flexDirection: 'column',
    rowGap: '24px',
  },
});

export const StyledLineChartColumn = styled.div({
  display: 'flex',
  flexDirection: 'column',
  minWidth: 0,
  position: 'relative',
  marginRight: `-${PHI_LINE_TO_BAR_CHART_OVERLAP}px`,
  boxSizing: 'border-box',

  '@media (max-width: 1096px)': {
    marginRight: 0,
  },
});

export const StyledBarChartColumn = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: `${BAR_CHART_MAX_WIDTH}px`,
  minWidth: 0,
  boxSizing: 'border-box',
  position: 'relative',
});

export const StyledChartWrapper = styled.div({
  height: DEFAULT_CHART_WRAPPER_HEIGHT,
  width: '100%',
  minWidth: 0,
  boxSizing: 'border-box',

  '@media (max-width: 1096px)': {
    height: '240px',
  },
});

export const StyledLineChartWrapper = styled(StyledChartWrapper)({
  margin: 0,
  padding: 0,
});

export const StyledPhiBarChartLegendRow = styled.div({
  position: 'absolute',
  top: 0,
  left: 0,
  zIndex: 1,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  width: '100%',
  minHeight: '32px',
  padding: '2px 0',
  boxSizing: 'border-box',
  pointerEvents: 'none',

  '& > div': {
    display: 'flex',
    flexDirection: 'row',
    flexWrap: 'wrap',
    justifyContent: 'center',
    gap: 8,
    pointerEvents: 'auto',
  },

  '& span': {
    whiteSpace: 'nowrap',
    fontSize: '10px',
    lineHeight: '12px',
  },
});
